export default {"index.html":"<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>Suno News Mirror — Your world. Your language.</title>\n  <meta name=\"description\" content=\"A calm, accessible text-to-speech reader for notices, study notes, and everyday messages across Indian languages.\">\n  <link rel=\"stylesheet\" href=\"styles.css\">\n  <link rel=\"stylesheet\" href=\"news.css\">\n</head>\n<body>\n  <a href=\"#main-content\" class=\"skip-link\">Skip to main content</a>\n\n  <header class=\"app-header\">\n    <div class=\"header-container\">\n      <div class=\"brand-bar\">\n        <div class=\"wordmark-group\">\n          <span class=\"wordmark\" aria-label=\"Suno\">Suno</span>\n          <span class=\"wordmark-tag\">Personal audio</span>\n        </div>\n        <div class=\"toolbar\" role=\"toolbar\" aria-label=\"Appearance preferences\">\n          <button type=\"button\" id=\"toggle-larger-text\" class=\"toolbar-btn\" aria-pressed=\"false\" title=\"Toggle larger text size\">\n            <span class=\"toolbar-icon\" aria-hidden=\"true\">A+</span>\n            <span>Larger text</span>\n          </button>\n          <button type=\"button\" id=\"toggle-high-contrast\" class=\"toolbar-btn\" aria-pressed=\"false\" title=\"Toggle high contrast display\">\n            <span class=\"toolbar-icon\" aria-hidden=\"true\">&#9681;</span>\n            <span>High contrast</span>\n          </button>\n        </div>\n      </div>\n\n      <div class=\"hero-copy\">\n        <p class=\"eyebrow\">YOUR WORLD. YOUR LANGUAGE. A VOICE LIKE YOURS.</p>\n        <h1 class=\"main-title\">The world. A little more familiar.</h1>\n        <p class=\"hero-desc\">\n          Your own listening edition of current news. Choose what matters, hear it in your language,\n          and try an AI recreation of your own voice. Or turn any everyday text into audio.\n        </p>\n      </div>\n\n      <div id=\"health-banner\" class=\"health-notice\" role=\"status\" hidden>\n        <div class=\"health-notice-content\">\n          <span class=\"health-icon\" aria-hidden=\"true\">&#9888;</span>\n          <span id=\"health-notice-text\">Notice: Server voice engine is currently unconfigured.</span>\n        </div>\n      </div>\n    </div>\n  </header>\n\n  <main id=\"main-content\" class=\"app-main\">\n    <div class=\"main-container reader-grid\">\n      <!-- Editor Card -->\n      <section class=\"card editor-card\" aria-labelledby=\"editor-heading\">\n        <div class=\"card-header\">\n          <h2 id=\"editor-heading\" class=\"card-title\">What would you like to hear?</h2>\n          <p class=\"card-subtitle\">Type or paste text below, or choose a common example to begin.</p>\n        </div>\n\n        <div class=\"sample-chips-group\" role=\"group\" aria-label=\"Sample text options\">\n          <span class=\"chips-label\">Try a sample:</span>\n          <div class=\"chips-list\">\n            <button type=\"button\" class=\"chip-btn\" data-sample=\"notice\">A daily notice</button>\n            <button type=\"button\" class=\"chip-btn\" data-sample=\"study\">A study note</button>\n            <button type=\"button\" class=\"chip-btn\" data-sample=\"message\">An everyday message</button>\n          </div>\n        </div>\n\n        <form id=\"reader-form\" class=\"editor-form\">\n          <div class=\"form-field\">\n            <div class=\"field-label-row\">\n              <label for=\"source-text\" class=\"field-label\">Text to read</label>\n              <span id=\"char-counter\" class=\"char-counter\" aria-live=\"polite\">0 / 1000 characters</span>\n            </div>\n            <textarea\n              id=\"source-text\"\n              name=\"text\"\n              rows=\"7\"\n              placeholder=\"Paste or write up to 1,000 characters here...\"\n              aria-describedby=\"char-counter text-hint\"\n              spellcheck=\"false\"\n            ></textarea>\n            <span id=\"text-hint\" class=\"field-hint\">Maximum 1,000 characters. Supports Indian scripts and English.</span>\n          </div>\n\n          <div class=\"languages-grid\">\n            <div class=\"form-field\">\n              <label for=\"source-lang\" class=\"field-label\">Original language</label>\n              <select id=\"source-lang\" name=\"sourceLanguage\" class=\"lang-select\">\n                <option value=\"en-IN\" selected>English (India)</option>\n                <option value=\"hi-IN\">हिन्दी — Hindi</option>\n                <option value=\"bn-IN\">বাংলা — Bengali</option>\n                <option value=\"gu-IN\">ગુજરાતી — Gujarati</option>\n                <option value=\"kn-IN\">ಕನ್ನಡ — Kannada</option>\n                <option value=\"ml-IN\">മലയാളം — Malayalam</option>\n                <option value=\"mr-IN\">मराठी — Marathi</option>\n                <option value=\"or-IN\">ଓଡ଼ିଆ — Odia</option>\n                <option value=\"pa-IN\">ਪੰਜਾਬੀ — Punjabi</option>\n                <option value=\"ta-IN\">தமிழ் — Tamil</option>\n                <option value=\"te-IN\">తెలుగు — Telugu</option>\n              </select>\n            </div>\n\n            <div class=\"form-field\">\n              <label for=\"target-lang\" class=\"field-label\">Listening language</label>\n              <select id=\"target-lang\" name=\"targetLanguage\" class=\"lang-select\">\n                <option value=\"hi-IN\" selected>हिन्दी — Hindi</option>\n                <option value=\"en-IN\">English (India)</option>\n                <option value=\"bn-IN\">বাংলা — Bengali</option>\n                <option value=\"gu-IN\">ગુજરાતી — Gujarati</option>\n                <option value=\"kn-IN\">ಕನ್ನಡ — Kannada</option>\n                <option value=\"ml-IN\">മലയാളം — Malayalam</option>\n                <option value=\"mr-IN\">मराठी — Marathi</option>\n                <option value=\"or-IN\">ଓଡ଼ିଆ — Odia</option>\n                <option value=\"pa-IN\">ਪੰਜਾਬੀ — Punjabi</option>\n                <option value=\"ta-IN\">தமிழ் — Tamil</option>\n                <option value=\"te-IN\">తెలుగు — Telugu</option>\n              </select>\n            </div>\n          </div>\n\n          <div class=\"form-actions\">\n            <button type=\"submit\" id=\"create-audio-btn\" class=\"btn btn-primary\" disabled>\n              <span class=\"btn-text\">Create audio</span>\n            </button>\n            <button type=\"button\" id=\"clear-btn\" class=\"btn btn-secondary\">\n              Clear\n            </button>\n          </div>\n        </form>\n      </section>\n\n      <!-- Output Card -->\n      <section class=\"card output-card\" aria-labelledby=\"output-heading\">\n        <div class=\"card-header\">\n          <h2 id=\"output-heading\" class=\"card-title\">Listening area</h2>\n          <p class=\"card-subtitle\">Your translated text and spoken audio will appear here.</p>\n        </div>\n\n        <div id=\"live-announcer\" class=\"sr-only\" aria-live=\"polite\" aria-atomic=\"true\"></div>\n\n        <!-- Alert messages (Error & Partial Error) -->\n        <div id=\"error-alert\" class=\"alert-box alert-error\" role=\"alert\" hidden>\n          <div class=\"alert-icon\" aria-hidden=\"true\">&#9888;</div>\n          <div class=\"alert-body\">\n            <strong class=\"alert-title\">Unable to generate audio</strong>\n            <p id=\"error-message\" class=\"alert-text\"></p>\n          </div>\n        </div>\n\n        <div id=\"partial-alert\" class=\"alert-box alert-warning\" role=\"alert\" hidden>\n          <div class=\"alert-icon\" aria-hidden=\"true\">&#9432;</div>\n          <div class=\"alert-body\">\n            <strong class=\"alert-title\">Spoken audio unavailable</strong>\n            <p id=\"partial-message\" class=\"alert-text\">\n              We translated your text, but voice generation could not be completed. You can read the prepared text below or try creating audio again.\n            </p>\n            <button type=\"button\" id=\"retry-audio-btn\" class=\"btn btn-secondary btn-sm\">Try audio again</button>\n          </div>\n        </div>\n\n        <!-- Empty State -->\n        <div id=\"empty-state\" class=\"state-container empty-state\">\n          <div class=\"empty-graphic\" aria-hidden=\"true\">\n            <svg class=\"illustration-svg\" viewBox=\"0 0 160 160\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\">\n              <circle cx=\"80\" cy=\"80\" r=\"70\" class=\"graphic-bg\" />\n              <!-- Open reading book -->\n              <path d=\"M46 102C56 97 68 97 80 102C92 97 104 97 114 102V62C104 57 92 57 80 62C68 57 56 57 46 62V102Z\" class=\"graphic-book\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/>\n              <path d=\"M80 62V102\" class=\"graphic-spine\" stroke-width=\"2.5\" stroke-linecap=\"round\"/>\n              <!-- Radiating acoustic listening waves -->\n              <path d=\"M36 74C32 78 32 86 36 90\" class=\"graphic-wave\" stroke-width=\"2.5\" stroke-linecap=\"round\"/>\n              <path d=\"M28 68C22 75 22 89 28 96\" class=\"graphic-wave\" stroke-width=\"2.5\" stroke-linecap=\"round\"/>\n              <path d=\"M124 74C128 78 128 86 124 90\" class=\"graphic-wave\" stroke-width=\"2.5\" stroke-linecap=\"round\"/>\n              <path d=\"M132 68C138 75 138 89 132 96\" class=\"graphic-wave\" stroke-width=\"2.5\" stroke-linecap=\"round\"/>\n            </svg>\n          </div>\n          <h3 class=\"state-title\">Ready when you are</h3>\n          <p class=\"state-desc\">Enter text in the editor and click \"Create audio\". Your spoken reading and translated words will be generated here.</p>\n        </div>\n\n        <!-- Loading State -->\n        <div id=\"loading-state\" class=\"state-container loading-state\" hidden aria-busy=\"true\">\n          <div class=\"spinner\" aria-hidden=\"true\"></div>\n          <h3 class=\"state-title\">Creating spoken audio...</h3>\n          <p class=\"state-desc\">Contacting Sarvam AI speech engine to translate and synthesize clear speech. This may take a few moments.</p>\n        </div>\n\n        <!-- Output Result Panel (Text & Audio) -->\n        <div id=\"result-panel\" class=\"result-panel\" hidden>\n          <div class=\"result-meta-bar\">\n            <span id=\"result-badge\" class=\"badge\">Original text</span>\n            <span id=\"result-lang-tag\" class=\"lang-tag\"></span>\n          </div>\n\n          <div class=\"text-output-section\">\n            <div class=\"text-output-header\">\n              <span class=\"text-output-title\">Readable text</span>\n              <button type=\"button\" id=\"copy-text-btn\" class=\"btn-copy\" aria-label=\"Copy text to clipboard\">\n                <span id=\"copy-btn-text\">Copy text</span>\n              </button>\n            </div>\n            <div id=\"output-text\" class=\"output-text-content\" tabindex=\"0\" lang=\"hi-IN\"></div>\n          </div>\n\n          <div id=\"audio-section\" class=\"audio-section\">\n            <label for=\"audio-player\" class=\"field-label\">Spoken recording</label>\n            <div class=\"audio-player-wrapper\">\n              <audio id=\"audio-player\" controls preload=\"metadata\"></audio>\n            </div>\n\n            <div class=\"playback-speed-group\" role=\"group\" aria-label=\"Playback speed\">\n              <span class=\"speed-label\">Speed:</span>\n              <div class=\"speed-buttons\">\n                <button type=\"button\" class=\"speed-btn\" data-speed=\"0.75\" aria-pressed=\"false\">0.75x</button>\n                <button type=\"button\" class=\"speed-btn active\" data-speed=\"1\" aria-pressed=\"true\">1x</button>\n                <button type=\"button\" class=\"speed-btn\" data-speed=\"1.25\" aria-pressed=\"false\">1.25x</button>\n                <button type=\"button\" class=\"speed-btn\" data-speed=\"1.5\" aria-pressed=\"false\">1.5x</button>\n              </div>\n            </div>\n\n            <div class=\"download-row\">\n              <a id=\"download-btn\" class=\"btn btn-download\" download=\"suno-reading.wav\" href=\"#\">\n                <span class=\"download-icon\" aria-hidden=\"true\">&#10515;</span>\n                Download suno-reading.wav\n              </a>\n            </div>\n          </div>\n        </div>\n      </section>\n    </div>\n  </main>\n\n  <footer class=\"app-footer\">\n    <div class=\"footer-container\">\n      <p class=\"footer-tagline\">Made for listening. Powered by Sarvam AI.</p>\n      <p class=\"footer-disclaimer\">\n        Speech generation sends your text securely to Sarvam AI language models over the internet.\n        Suno does not save your text or audio history. Sarvam's own data policies apply.\n      </p>\n    </div>\n  </footer>\n\n  <script src=\"app.js\" defer></script>\n  <script src=\"news.js\" defer></script>\n  <script src=\"voice-recorder.js\" defer></script>\n</body>\n</html>\n","app.js":"/**\n * Suno Accessible Reader Interface\n * Vanilla JS implementation compliant with briefs/T-ui.md and PLAN.md\n */\n\n(() => {\n  'use strict';\n\n  // Language names mapping for accessible display\n  const LANGUAGE_NAMES = {\n    'en-IN': 'English (India)',\n    'hi-IN': 'हिन्दी (Hindi)',\n    'bn-IN': 'বাংলা (Bengali)',\n    'gu-IN': 'ગુજરાતી (Gujarati)',\n    'kn-IN': 'ಕನ್ನಡ (Kannada)',\n    'ml-IN': 'മലയാളം (Malayalam)',\n    'mr-IN': 'मराठी (Marathi)',\n    'or-IN': 'ଓଡ଼ିଆ (Odia)',\n    'pa-IN': 'ਪੰਜਾਬੀ (Punjabi)',\n    'ta-IN': 'தமிழ் (Tamil)',\n    'te-IN': 'తెలుగు (Telugu)'\n  };\n\n  // Sample texts for nontechnical readers\n  const SAMPLE_TEXTS = {\n    notice: 'Water supply notice: Routine maintenance on the main pipeline in Sector 4 is scheduled for tomorrow between 10:00 AM and 2:00 PM. Residents are advised to store necessary water in advance. Normal supply will resume by evening.',\n    study: 'Photosynthesis is the process green plants use to convert sunlight, water, and carbon dioxide into oxygen and energy-rich sugars. Chlorophyll in leaves absorbs the light, supplying oxygen for life on Earth.',\n    message: 'Hello neighbors! The community library book circle meets this Saturday at 4:00 PM in the community hall. Feel free to bring a friend, discuss stories, and pick out new books for the month.'\n  };\n\n  // DOM Elements\n  const sourceText = document.getElementById('source-text');\n  const charCounter = document.getElementById('char-counter');\n  const sourceLang = document.getElementById('source-lang');\n  const targetLang = document.getElementById('target-lang');\n  const createAudioBtn = document.getElementById('create-audio-btn');\n  const clearBtn = document.getElementById('clear-btn');\n  const sampleButtons = document.querySelectorAll('.chip-btn');\n  const readerForm = document.getElementById('reader-form');\n\n  // Appearance Toolbar\n  const toggleLargerTextBtn = document.getElementById('toggle-larger-text');\n  const toggleHighContrastBtn = document.getElementById('toggle-high-contrast');\n\n  // Health Notice Banner\n  const healthBanner = document.getElementById('health-banner');\n  const healthNoticeText = document.getElementById('health-notice-text');\n\n  // Output Card & States\n  const liveAnnouncer = document.getElementById('live-announcer');\n  const emptyState = document.getElementById('empty-state');\n  const loadingState = document.getElementById('loading-state');\n  const resultPanel = document.getElementById('result-panel');\n  const errorAlert = document.getElementById('error-alert');\n  const errorMessage = document.getElementById('error-message');\n  const partialAlert = document.getElementById('partial-alert');\n  const partialMessage = document.getElementById('partial-message');\n  const retryAudioBtn = document.getElementById('retry-audio-btn');\n\n  // Results & Audio Elements\n  const resultBadge = document.getElementById('result-badge');\n  const resultLangTag = document.getElementById('result-lang-tag');\n  const outputText = document.getElementById('output-text');\n  const copyTextBtn = document.getElementById('copy-text-btn');\n  const copyBtnText = document.getElementById('copy-btn-text');\n  const audioSection = document.getElementById('audio-section');\n  const audioPlayer = document.getElementById('audio-player');\n  const speedButtons = document.querySelectorAll('.speed-btn');\n  const downloadBtn = document.getElementById('download-btn');\n\n  // Application State\n  let currentAudioUrl = null;\n  let currentAbortController = null;\n  let currentPlaybackSpeed = 1.0;\n  let isRequestInProgress = false;\n\n  /**\n   * Helper: Count Unicode code points properly (handling surrogate pairs)\n   */\n  function countCodePoints(str) {\n    return Array.from(str || '').length;\n  }\n\n  /**\n   * Screen reader announcer\n   */\n  function announce(message) {\n    if (liveAnnouncer) {\n      liveAnnouncer.textContent = '';\n      // Small timeout ensures screen readers detect text change\n      setTimeout(() => {\n        liveAnnouncer.textContent = message;\n      }, 50);\n    }\n  }\n\n  /**\n   * Appearance preference toggles\n   * Stores preferences only in localStorage (never user text)\n   */\n  function initAppearancePreferences() {\n    try {\n      const isLargerText = localStorage.getItem('suno_larger_text') === 'true';\n      if (isLargerText) {\n        document.documentElement.classList.add('larger-text');\n        toggleLargerTextBtn.setAttribute('aria-pressed', 'true');\n      }\n\n      const isHighContrast = localStorage.getItem('suno_high_contrast') === 'true';\n      if (isHighContrast) {\n        document.documentElement.classList.add('high-contrast');\n        toggleHighContrastBtn.setAttribute('aria-pressed', 'true');\n      }\n    } catch {\n      // Ignore localStorage availability errors\n    }\n\n    toggleLargerTextBtn.addEventListener('click', () => {\n      const active = document.documentElement.classList.toggle('larger-text');\n      toggleLargerTextBtn.setAttribute('aria-pressed', active ? 'true' : 'false');\n      try {\n        localStorage.setItem('suno_larger_text', active ? 'true' : 'false');\n      } catch {}\n      announce(active ? 'Larger text enabled.' : 'Larger text disabled.');\n    });\n\n    toggleHighContrastBtn.addEventListener('click', () => {\n      const active = document.documentElement.classList.toggle('high-contrast');\n      toggleHighContrastBtn.setAttribute('aria-pressed', active ? 'true' : 'false');\n      try {\n        localStorage.setItem('suno_high_contrast', active ? 'true' : 'false');\n      } catch {}\n      announce(active ? 'High contrast enabled.' : 'High contrast disabled.');\n    });\n  }\n\n  /**\n   * Update character counter and button validation\n   */\n  function updateCharacterCount() {\n    const text = sourceText.value;\n    const count = countCodePoints(text);\n    charCounter.textContent = `${count} / 1000 characters`;\n\n    if (count > 1000) {\n      charCounter.classList.add('char-limit-exceeded');\n      sourceText.setAttribute('aria-invalid', 'true');\n      createAudioBtn.disabled = true;\n    } else {\n      charCounter.classList.remove('char-limit-exceeded');\n      sourceText.removeAttribute('aria-invalid');\n      createAudioBtn.disabled = (!text.trim() || isRequestInProgress);\n    }\n  }\n\n  /**\n   * Clean up old audio Blob URL to prevent memory leaks\n   */\n  function revokeAudioUrl() {\n    if (currentAudioUrl) {\n      URL.revokeObjectURL(currentAudioUrl);\n      currentAudioUrl = null;\n    }\n    if (audioPlayer) {\n      audioPlayer.pause();\n      audioPlayer.removeAttribute('src');\n      audioPlayer.load();\n    }\n    if (downloadBtn) {\n      downloadBtn.removeAttribute('href');\n    }\n  }\n\n  /**\n   * Reset the output panel back to the clean empty state\n   */\n  function showEmptyState() {\n    revokeAudioUrl();\n    emptyState.hidden = false;\n    loadingState.hidden = true;\n    resultPanel.hidden = true;\n    errorAlert.hidden = true;\n    partialAlert.hidden = true;\n  }\n\n  /**\n   * Display loading state\n   */\n  function showLoadingState() {\n    revokeAudioUrl();\n    emptyState.hidden = true;\n    loadingState.hidden = false;\n    errorAlert.hidden = true;\n    partialAlert.hidden = true;\n    // Don't hide resultPanel completely if previous text was showing, but keep it quiet\n    resultPanel.hidden = true;\n    announce('Creating spoken audio. Please wait.');\n  }\n\n  /**\n   * Display general error alert\n   */\n  function showErrorAlert(message) {\n    revokeAudioUrl();\n    loadingState.hidden = true;\n    errorAlert.hidden = false;\n    errorMessage.textContent = message;\n    partialAlert.hidden = true;\n    announce(`Error: ${message}`);\n  }\n\n  /**\n   * Display partial error state (HTTP 502 with translated text)\n   * The text remains visible, audio is cleared, retry is available\n   */\n  function showPartialError(text, targetLangCode, errorDetail, translated) {\n    revokeAudioUrl();\n    loadingState.hidden = true;\n    emptyState.hidden = true;\n    errorAlert.hidden = true;\n    partialAlert.hidden = false;\n\n    if (errorDetail) {\n      partialMessage.textContent = `Text was prepared, but audio could not be generated: ${errorDetail}`;\n    } else {\n      partialMessage.textContent = 'Text was prepared, but voice generation could not be completed. You can read the prepared text below or try creating audio again.';\n    }\n\n    // Render returned text\n    renderResultText(text, targetLangCode, Boolean(translated));\n    // Hide audio section since audio failed\n    audioSection.hidden = true;\n    resultPanel.hidden = false;\n\n    announce('Text prepared, but voice generation failed. You can read the text below.');\n  }\n\n  /**\n   * Render result text safely using textContent\n   */\n  function renderResultText(text, targetLangCode, isTranslated) {\n    outputText.textContent = text;\n    outputText.setAttribute('lang', targetLangCode);\n\n    if (isTranslated) {\n      resultBadge.textContent = 'Translated text';\n    } else {\n      resultBadge.textContent = 'Original text';\n    }\n\n    const langLabel = LANGUAGE_NAMES[targetLangCode] || targetLangCode;\n    resultLangTag.textContent = langLabel;\n  }\n\n  /**\n   * Convert Base64 string to Blob\n   */\n  function base64ToBlob(base64, mimeType = 'audio/wav') {\n    const binary = atob(base64);\n    const len = binary.length;\n    const bytes = new Uint8Array(len);\n    for (let i = 0; i < len; i++) {\n      bytes[i] = binary.charCodeAt(i);\n    }\n    return new Blob([bytes], { type: mimeType });\n  }\n\n  /**\n   * Handle successful response\n   */\n  function handleSuccess(data, targetLangCode) {\n    revokeAudioUrl();\n    loadingState.hidden = true;\n    emptyState.hidden = true;\n    errorAlert.hidden = true;\n    partialAlert.hidden = true;\n\n    // Render text\n    renderResultText(data.text, targetLangCode, Boolean(data.translated));\n\n    // Prepare audio blob\n    if (data.audioBase64) {\n      const mime = data.mimeType || 'audio/wav';\n      const blob = base64ToBlob(data.audioBase64, mime);\n      currentAudioUrl = URL.createObjectURL(blob);\n\n      audioPlayer.src = currentAudioUrl;\n      audioPlayer.playbackRate = currentPlaybackSpeed;\n      audioSection.hidden = false;\n\n      downloadBtn.href = currentAudioUrl;\n      downloadBtn.download = 'suno-reading.wav';\n    } else {\n      audioSection.hidden = true;\n    }\n\n    resultPanel.hidden = false;\n    announce('Spoken audio and text are ready.');\n  }\n\n  /**\n   * Submit text for translation and TTS\n   */\n  async function submitReadRequest() {\n    const text = sourceText.value.trim();\n    if (!text || countCodePoints(text) > 1000) {\n      return;\n    }\n\n    if (isRequestInProgress) {\n      return; // Prevent duplicate requests\n    }\n\n    isRequestInProgress = true;\n    createAudioBtn.disabled = true;\n    createAudioBtn.setAttribute('aria-busy', 'true');\n    showLoadingState();\n\n    const srcLang = sourceLang.value;\n    const tgtLang = targetLang.value;\n\n    currentAbortController = new AbortController();\n\n    try {\n      const response = await fetch('/api/read', {\n        method: 'POST',\n        headers: {\n          'Content-Type': 'application/json'\n        },\n        body: JSON.stringify({\n          text: text,\n          sourceLanguage: srcLang,\n          targetLanguage: tgtLang\n        }),\n        signal: currentAbortController.signal\n      });\n\n      let responseData = null;\n      try {\n        responseData = await response.json();\n      } catch {\n        responseData = null;\n      }\n\n      if (response.ok && responseData) {\n        handleSuccess(responseData, tgtLang);\n      } else if (response.status === 502 && responseData && responseData.text) {\n        // Partial failure: translated text provided, speech failed\n        showPartialError(responseData.text, tgtLang, responseData.error, responseData.translated);\n      } else {\n        const errorMsg = (responseData && responseData.error)\n          ? responseData.error\n          : `Request failed with server status ${response.status}.`;\n        showErrorAlert(errorMsg);\n      }\n    } catch (err) {\n      if (err.name === 'AbortError') {\n        // Request cancelled by user\n        showEmptyState();\n        announce('Request was cancelled.');\n      } else {\n        showErrorAlert('Unable to connect to the server. Please check your internet connection.');\n      }\n    } finally {\n      isRequestInProgress = false;\n      currentAbortController = null;\n      createAudioBtn.removeAttribute('aria-busy');\n      updateCharacterCount();\n    }\n  }\n\n  /**\n   * Reset / Clear editor and output\n   */\n  function handleClear() {\n    if (currentAbortController) {\n      currentAbortController.abort();\n    }\n    sourceText.value = '';\n    updateCharacterCount();\n    showEmptyState();\n    sourceText.focus();\n    announce('Editor cleared.');\n  }\n\n  /**\n   * Check backend server configuration health\n   * GET /api/health -> { ok: true, configured: boolean }\n   */\n  async function checkHealth() {\n    try {\n      const res = await fetch('/api/health');\n      if (!res.ok) {\n        healthNoticeText.textContent = `Notice: Server responded with status ${res.status}. Voice generation may be unavailable.`;\n        healthBanner.hidden = false;\n        return;\n      }\n      const data = await res.json();\n      if (data && data.configured === false) {\n        healthNoticeText.textContent = 'Audio is not available yet. Ask the person hosting Suno to finish the voice setup.';\n        healthBanner.hidden = false;\n      } else {\n        healthBanner.hidden = true;\n      }\n    } catch {\n      healthNoticeText.textContent = 'Suno could not connect. Please check your connection or ask the person hosting this reader for help.';\n      healthBanner.hidden = false;\n    }\n  }\n\n  /**\n   * Copy output text to clipboard\n   */\n  async function copyOutputText() {\n    const text = outputText.textContent;\n    if (!text) return;\n\n    try {\n      await navigator.clipboard.writeText(text);\n      copyBtnText.textContent = 'Copied!';\n      setTimeout(() => {\n        copyBtnText.textContent = 'Copy text';\n      }, 2000);\n      announce('Text copied to clipboard.');\n    } catch {\n      // Fallback\n      copyBtnText.textContent = 'Selected';\n      announce('Unable to automatically copy. Please copy manually.');\n    }\n  }\n\n  /**\n   * Playback speed selection handler\n   */\n  function setPlaybackSpeed(rate) {\n    currentPlaybackSpeed = rate;\n    if (audioPlayer) {\n      audioPlayer.playbackRate = rate;\n    }\n    speedButtons.forEach(btn => {\n      const btnRate = parseFloat(btn.dataset.speed);\n      const isActive = Math.abs(btnRate - rate) < 0.01;\n      btn.classList.toggle('active', isActive);\n      btn.setAttribute('aria-pressed', isActive ? 'true' : 'false');\n    });\n  }\n\n  /**\n   * Initialize event listeners\n   */\n  function initEvents() {\n    // Textarea input count\n    sourceText.addEventListener('input', updateCharacterCount);\n\n    // Form submission\n    readerForm.addEventListener('submit', (e) => {\n      e.preventDefault();\n      submitReadRequest();\n    });\n\n    createAudioBtn.addEventListener('click', (e) => {\n      e.preventDefault();\n      submitReadRequest();\n    });\n\n    // Clear button\n    clearBtn.addEventListener('click', handleClear);\n\n    // Retry audio button\n    if (retryAudioBtn) {\n      retryAudioBtn.addEventListener('click', submitReadRequest);\n    }\n\n    // Sample chip buttons\n    sampleButtons.forEach(btn => {\n      btn.addEventListener('click', () => {\n        const sampleKey = btn.dataset.sample;\n        const text = SAMPLE_TEXTS[sampleKey];\n        if (text) {\n          sourceText.value = text;\n          sourceLang.value = 'en-IN';\n          updateCharacterCount();\n          sourceText.focus();\n          announce(`Loaded sample: ${btn.textContent}`);\n        }\n      });\n    });\n\n    // Playback speed buttons\n    speedButtons.forEach(btn => {\n      btn.addEventListener('click', () => {\n        const rate = parseFloat(btn.dataset.speed);\n        if (!isNaN(rate)) {\n          setPlaybackSpeed(rate);\n        }\n      });\n    });\n\n    // Reapply playback rate if audio loads/changes\n    audioPlayer.addEventListener('loadedmetadata', () => {\n      audioPlayer.playbackRate = currentPlaybackSpeed;\n    });\n\n    // Copy text button\n    copyTextBtn.addEventListener('click', copyOutputText);\n  }\n\n  // Initialize\n  initAppearancePreferences();\n  initEvents();\n  updateCharacterCount();\n  checkHealth();\n})();\n","styles.css":"/* ==========================================================================\n   Suno Reader — Accessible, Editorial, Calm Warm-Ivory Interface\n   ========================================================================== */\n\n[hidden] { display: none !important; }\n\n/* Design Tokens & Theme Variables */\n:root {\n  /* Warm Ivory & Dark Ink Palette */\n  --color-bg: #F9F7F2;\n  --color-bg-subtle: #F2EFE8;\n  --color-card-bg: #FFFFFF;\n  --color-card-border: #E2DBD0;\n  --color-card-border-focus: #1E4632;\n  \n  --color-ink: #1B211E;\n  --color-ink-muted: #4F5A54;\n  --color-ink-subtle: #728078;\n  \n  /* Muted Forest Green Accents */\n  --color-forest: #1E4632;\n  --color-forest-hover: #153324;\n  --color-forest-active: #0F251A;\n  --color-forest-tint: #EEF4F0;\n  --color-forest-border: #BACDC1;\n  --color-forest-contrast: #FFFFFF;\n  \n  /* Status Colors */\n  --color-error-bg: #FDF3F2;\n  --color-error-border: #E89E9B;\n  --color-error-text: #8E1F1D;\n  --color-error-accent: #C53030;\n  \n  --color-warning-bg: #FFF9EB;\n  --color-warning-border: #E5CE85;\n  --color-warning-text: #6E4E00;\n  --color-warning-accent: #B7791F;\n\n  --color-badge-bg: #EAE6DD;\n  --color-badge-text: #2A332E;\n\n  /* Typography */\n  --font-editorial: Charter, \"Bitstream Charter\", \"Sitka Text\", Cambria, Georgia, \"Times New Roman\", serif;\n  --font-ui: system-ui, -apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, \"Helvetica Neue\", Arial, sans-serif;\n  \n  --line-height-body: 1.6;\n  --line-height-heading: 1.25;\n\n  /* Focus & Elevation */\n  --focus-outline-width: 3px;\n  --focus-outline-color: #1E4632;\n  --focus-outline-offset: 2px;\n  --shadow-card: 0 4px 16px rgba(27, 33, 30, 0.05);\n\n  /* Touch Targets */\n  --min-touch-size: 44px;\n}\n\n/* High Contrast Mode */\nhtml.high-contrast {\n  --color-bg: #000000;\n  --color-bg-subtle: #121212;\n  --color-card-bg: #080808;\n  --color-card-border: #FFFFFF;\n  --color-card-border-focus: #FFFF00;\n\n  --color-ink: #FFFFFF;\n  --color-ink-muted: #E6E6E6;\n  --color-ink-subtle: #CCCCCC;\n\n  --color-forest: #FFFF00;\n  --color-forest-hover: #FFFFFF;\n  --color-forest-active: #FFD700;\n  --color-forest-tint: #242400;\n  --color-forest-border: #FFFF00;\n  --color-forest-contrast: #000000;\n\n  --color-error-bg: #2B0000;\n  --color-error-border: #FF8080;\n  --color-error-text: #FFCCCC;\n  --color-error-accent: #FF5555;\n\n  --color-warning-bg: #2B1D00;\n  --color-warning-border: #FFE066;\n  --color-warning-text: #FFF0A6;\n  --color-warning-accent: #FFD13B;\n\n  --color-badge-bg: #333333;\n  --color-badge-text: #FFFF00;\n\n  --focus-outline-color: #FFFF00;\n  --shadow-card: none;\n}\n\n/* Larger Text Mode */\nhtml.larger-text {\n  font-size: 118%;\n}\n\n/* Base Reset & Box Sizing */\n*, *::before, *::after {\n  box-sizing: border-box;\n  margin: 0;\n  padding: 0;\n}\n\nbody {\n  font-family: var(--font-ui);\n  font-size: 1rem;\n  line-height: var(--line-height-body);\n  color: var(--color-ink);\n  background-color: var(--color-bg);\n  min-height: 100vh;\n  display: flex;\n  flex-direction: column;\n  -webkit-font-smoothing: antialiased;\n  -moz-osx-font-smoothing: grayscale;\n}\n\n/* Accessibility: Skip Link */\n.skip-link {\n  position: absolute;\n  top: -100px;\n  left: 1rem;\n  background: var(--color-forest);\n  color: var(--color-forest-contrast);\n  padding: 0.75rem 1.25rem;\n  border-radius: 4px;\n  text-decoration: none;\n  font-weight: 600;\n  z-index: 1000;\n  transition: top 0.2s ease;\n}\n\n.skip-link:focus {\n  top: 1rem;\n  outline: var(--focus-outline-width) solid var(--focus-outline-color);\n  outline-offset: var(--focus-outline-offset);\n}\n\n/* Screen reader only utility */\n.sr-only {\n  position: absolute;\n  width: 1px;\n  height: 1px;\n  padding: 0;\n  margin: -1px;\n  overflow: hidden;\n  clip: rect(0, 0, 0, 0);\n  white-space: nowrap;\n  border: 0;\n}\n\n/* Focus styles for keyboard navigation */\n:focus-visible {\n  outline: var(--focus-outline-width) solid var(--focus-outline-color);\n  outline-offset: var(--focus-outline-offset);\n}\n\n/* Header & Brand */\n.app-header {\n  border-bottom: 1px solid var(--color-card-border);\n  background-color: var(--color-bg);\n  padding: 1.25rem 1.5rem 2rem;\n}\n\n.header-container {\n  max-width: 1120px;\n  margin: 0 auto;\n}\n\n.brand-bar {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  flex-wrap: wrap;\n  gap: 1rem;\n  margin-bottom: 2rem;\n}\n\n.wordmark-group {\n  display: inline-flex;\n  align-items: baseline;\n  gap: 0.5rem;\n}\n\n.wordmark {\n  font-family: var(--font-editorial);\n  font-size: 2rem;\n  font-weight: 700;\n  letter-spacing: -0.03em;\n  color: var(--color-forest);\n  line-height: 1;\n}\n\n.wordmark-tag {\n  font-family: var(--font-ui);\n  font-size: 0.8125rem;\n  font-weight: 600;\n  text-transform: uppercase;\n  letter-spacing: 0.08em;\n  color: var(--color-ink-muted);\n  background: var(--color-bg-subtle);\n  padding: 0.2rem 0.5rem;\n  border-radius: 4px;\n  border: 1px solid var(--color-card-border);\n}\n\n/* Appearance Toolbar */\n.toolbar {\n  display: flex;\n  align-items: center;\n  gap: 0.625rem;\n}\n\n.toolbar-btn {\n  display: inline-flex;\n  align-items: center;\n  gap: 0.5rem;\n  min-height: var(--min-touch-size);\n  padding: 0.5rem 0.875rem;\n  font-family: var(--font-ui);\n  font-size: 0.875rem;\n  font-weight: 600;\n  color: var(--color-ink);\n  background-color: var(--color-card-bg);\n  border: 1px solid var(--color-card-border);\n  border-radius: 6px;\n  cursor: pointer;\n  transition: all 0.15s ease;\n}\n\n.toolbar-btn:hover {\n  background-color: var(--color-forest-tint);\n  border-color: var(--color-forest-border);\n}\n\n.toolbar-btn[aria-pressed=\"true\"] {\n  background-color: var(--color-forest);\n  color: var(--color-forest-contrast);\n  border-color: var(--color-forest);\n}\n\n.toolbar-icon {\n  font-size: 1rem;\n  font-weight: 700;\n}\n\n/* Hero Section */\n.hero-copy {\n  max-width: 760px;\n}\n\n.eyebrow {\n  font-size: 0.8125rem;\n  font-weight: 700;\n  text-transform: uppercase;\n  letter-spacing: 0.12em;\n  color: var(--color-forest);\n  margin-bottom: 0.625rem;\n}\n\n.main-title {\n  font-family: var(--font-editorial);\n  font-size: clamp(2.25rem, 5vw, 3.25rem);\n  font-weight: 700;\n  line-height: 1.15;\n  color: var(--color-ink);\n  margin-bottom: 0.875rem;\n  letter-spacing: -0.02em;\n}\n\n.hero-desc {\n  font-size: 1.125rem;\n  line-height: 1.55;\n  color: var(--color-ink-muted);\n}\n\n/* Health Notice Banner */\n.health-notice {\n  margin-top: 1.5rem;\n  padding: 0.875rem 1.125rem;\n  background-color: var(--color-warning-bg);\n  border: 1px solid var(--color-warning-border);\n  border-radius: 8px;\n  color: var(--color-warning-text);\n  font-size: 0.9375rem;\n  line-height: 1.45;\n}\n\n.health-notice-content {\n  display: flex;\n  align-items: flex-start;\n  gap: 0.75rem;\n}\n\n.health-icon {\n  font-size: 1.25rem;\n  line-height: 1;\n  color: var(--color-warning-accent);\n}\n\n/* Main Layout & Grid */\n.app-main {\n  flex: 1;\n  padding: 2.25rem 1.5rem 3rem;\n}\n\n.main-container {\n  max-width: 1120px;\n  margin: 0 auto;\n}\n\n.reader-grid {\n  display: grid;\n  grid-template-columns: minmax(0, 1.05fr) minmax(0, 0.95fr);\n  gap: 2rem;\n  align-items: start;\n}\n\n/* Cards */\n.card {\n  background-color: var(--color-card-bg);\n  border: 1px solid var(--color-card-border);\n  border-radius: 12px;\n  padding: 2rem;\n  box-shadow: var(--shadow-card);\n}\n\n.card-header {\n  margin-bottom: 1.5rem;\n  border-bottom: 1px solid var(--color-card-border);\n  padding-bottom: 1.125rem;\n}\n\n.card-title {\n  font-family: var(--font-editorial);\n  font-size: 1.5rem;\n  font-weight: 700;\n  color: var(--color-ink);\n  margin-bottom: 0.35rem;\n  letter-spacing: -0.01em;\n}\n\n.card-subtitle {\n  font-size: 0.9375rem;\n  color: var(--color-ink-muted);\n}\n\n/* Sample Chips */\n.sample-chips-group {\n  margin-bottom: 1.5rem;\n}\n\n.chips-label {\n  display: block;\n  font-size: 0.8125rem;\n  font-weight: 600;\n  text-transform: uppercase;\n  letter-spacing: 0.06em;\n  color: var(--color-ink-muted);\n  margin-bottom: 0.5rem;\n}\n\n.chips-list {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 0.5rem;\n}\n\n.chip-btn {\n  min-height: var(--min-touch-size);\n  padding: 0.5rem 0.875rem;\n  font-family: var(--font-ui);\n  font-size: 0.875rem;\n  font-weight: 500;\n  color: var(--color-forest);\n  background-color: var(--color-forest-tint);\n  border: 1px solid var(--color-forest-border);\n  border-radius: 24px;\n  cursor: pointer;\n  transition: all 0.15s ease;\n  display: inline-flex;\n  align-items: center;\n}\n\n.chip-btn:hover {\n  background-color: #E2ECE5;\n  border-color: var(--color-forest);\n}\n\n/* Forms & Inputs */\n.editor-form {\n  display: flex;\n  flex-direction: column;\n  gap: 1.5rem;\n}\n\n.form-field {\n  display: flex;\n  flex-direction: column;\n  gap: 0.5rem;\n}\n\n.field-label-row {\n  display: flex;\n  justify-content: space-between;\n  align-items: baseline;\n  flex-wrap: wrap;\n  gap: 0.5rem;\n}\n\n.field-label {\n  font-size: 0.9375rem;\n  font-weight: 600;\n  color: var(--color-ink);\n}\n\n.char-counter {\n  font-size: 0.875rem;\n  font-variant-numeric: tabular-nums;\n  color: var(--color-ink-subtle);\n  font-weight: 500;\n}\n\n.char-counter.char-limit-exceeded {\n  color: var(--color-error-text);\n  font-weight: 700;\n}\n\ntextarea {\n  width: 100%;\n  font-family: var(--font-ui);\n  font-size: 1rem;\n  line-height: 1.6;\n  color: var(--color-ink);\n  background-color: var(--color-card-bg);\n  border: 1.5px solid var(--color-card-border);\n  border-radius: 8px;\n  padding: 0.875rem 1rem;\n  resize: vertical;\n  min-height: 160px;\n  transition: border-color 0.15s ease;\n}\n\ntextarea:focus {\n  border-color: var(--color-card-border-focus);\n}\n\ntextarea[aria-invalid=\"true\"] {\n  border-color: var(--color-error-accent);\n}\n\n.field-hint {\n  font-size: 0.8125rem;\n  color: var(--color-ink-subtle);\n}\n\n/* Language Selection Grid */\n.languages-grid {\n  display: grid;\n  grid-template-columns: 1fr 1fr;\n  gap: 1rem;\n}\n\n.lang-select {\n  width: 100%;\n  min-height: var(--min-touch-size);\n  padding: 0.625rem 0.875rem;\n  font-family: var(--font-ui);\n  font-size: 0.9375rem;\n  font-weight: 500;\n  color: var(--color-ink);\n  background-color: var(--color-card-bg);\n  border: 1.5px solid var(--color-card-border);\n  border-radius: 8px;\n  cursor: pointer;\n  appearance: auto;\n}\n\n.lang-select:focus {\n  border-color: var(--color-card-border-focus);\n}\n\n/* Buttons */\n.form-actions {\n  display: flex;\n  align-items: center;\n  gap: 0.875rem;\n  padding-top: 0.5rem;\n}\n\n.btn {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  gap: 0.5rem;\n  min-height: var(--min-touch-size);\n  padding: 0.625rem 1.375rem;\n  font-family: var(--font-ui);\n  font-size: 1rem;\n  font-weight: 600;\n  border-radius: 8px;\n  cursor: pointer;\n  text-decoration: none;\n  transition: all 0.15s ease;\n}\n\n.btn-primary {\n  background-color: var(--color-forest);\n  color: var(--color-forest-contrast);\n  border: 1.5px solid var(--color-forest);\n}\n\n.btn-primary:hover:not(:disabled) {\n  background-color: var(--color-forest-hover);\n  border-color: var(--color-forest-hover);\n}\n\n.btn-primary:active:not(:disabled) {\n  background-color: var(--color-forest-active);\n}\n\n.btn-primary:disabled {\n  opacity: 0.5;\n  cursor: not-allowed;\n}\n\n.btn-secondary {\n  background-color: transparent;\n  color: var(--color-ink-muted);\n  border: 1.5px solid var(--color-card-border);\n}\n\n.btn-secondary:hover:not(:disabled) {\n  background-color: var(--color-bg-subtle);\n  color: var(--color-ink);\n  border-color: var(--color-ink-subtle);\n}\n\n.btn-sm {\n  min-height: 38px;\n  padding: 0.4rem 0.875rem;\n  font-size: 0.875rem;\n}\n\n.btn-download {\n  background-color: var(--color-forest-tint);\n  color: var(--color-forest);\n  border: 1.5px solid var(--color-forest-border);\n  width: 100%;\n}\n\n.btn-download:hover {\n  background-color: #E2ECE5;\n  border-color: var(--color-forest);\n}\n\n.download-icon {\n  font-size: 1.125rem;\n  line-height: 1;\n}\n\n/* Alerts & Notices */\n.alert-box {\n  display: flex;\n  align-items: flex-start;\n  gap: 0.875rem;\n  padding: 1rem 1.25rem;\n  border-radius: 8px;\n  margin-bottom: 1.5rem;\n}\n\n.alert-error {\n  background-color: var(--color-error-bg);\n  border: 1px solid var(--color-error-border);\n  color: var(--color-error-text);\n}\n\n.alert-warning {\n  background-color: var(--color-warning-bg);\n  border: 1px solid var(--color-warning-border);\n  color: var(--color-warning-text);\n}\n\n.alert-icon {\n  font-size: 1.25rem;\n  line-height: 1;\n}\n\n.alert-title {\n  display: block;\n  font-size: 0.9375rem;\n  margin-bottom: 0.25rem;\n}\n\n.alert-text {\n  font-size: 0.875rem;\n  line-height: 1.45;\n  margin-bottom: 0.5rem;\n}\n\n/* Output Card States */\n.state-container {\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  justify-content: center;\n  text-align: center;\n  padding: 3rem 1.5rem;\n  min-height: 340px;\n}\n\n.empty-graphic {\n  width: 130px;\n  height: 130px;\n  margin-bottom: 1.25rem;\n}\n\n.illustration-svg {\n  width: 100%;\n  height: 100%;\n}\n\n.graphic-bg {\n  fill: var(--color-forest-tint);\n}\n\n.graphic-book {\n  fill: var(--color-card-bg);\n  stroke: var(--color-forest);\n}\n\n.graphic-spine {\n  stroke: var(--color-forest);\n}\n\n.graphic-wave {\n  stroke: var(--color-forest);\n}\n\n.state-title {\n  font-family: var(--font-editorial);\n  font-size: 1.375rem;\n  font-weight: 700;\n  color: var(--color-ink);\n  margin-bottom: 0.5rem;\n}\n\n.state-desc {\n  font-size: 0.9375rem;\n  color: var(--color-ink-muted);\n  max-width: 380px;\n  line-height: 1.5;\n}\n\n/* Loading Spinner */\n.spinner {\n  width: 44px;\n  height: 44px;\n  border: 4px solid var(--color-forest-tint);\n  border-top-color: var(--color-forest);\n  border-radius: 50%;\n  animation: suno-spin 0.9s linear infinite;\n  margin-bottom: 1.25rem;\n}\n\n@keyframes suno-spin {\n  to { transform: rotate(360deg); }\n}\n\n@media (prefers-reduced-motion: reduce) {\n  .spinner {\n    animation: none;\n    border-style: dotted;\n  }\n}\n\n/* Result Panel */\n.result-panel {\n  display: flex;\n  flex-direction: column;\n  gap: 1.5rem;\n}\n\n.result-meta-bar {\n  display: flex;\n  align-items: center;\n  gap: 0.75rem;\n}\n\n.badge {\n  display: inline-block;\n  padding: 0.25rem 0.625rem;\n  font-size: 0.75rem;\n  font-weight: 700;\n  text-transform: uppercase;\n  letter-spacing: 0.06em;\n  background-color: var(--color-forest-tint);\n  color: var(--color-forest);\n  border-radius: 4px;\n  border: 1px solid var(--color-forest-border);\n}\n\n.lang-tag {\n  font-size: 0.8125rem;\n  color: var(--color-ink-muted);\n  font-weight: 500;\n}\n\n/* Text Output */\n.text-output-section {\n  border: 1px solid var(--color-card-border);\n  border-radius: 8px;\n  padding: 1.125rem;\n  background-color: var(--color-bg);\n}\n\n.text-output-header {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  margin-bottom: 0.75rem;\n  padding-bottom: 0.5rem;\n  border-bottom: 1px solid var(--color-card-border);\n}\n\n.text-output-title {\n  font-size: 0.8125rem;\n  font-weight: 700;\n  text-transform: uppercase;\n  letter-spacing: 0.08em;\n  color: var(--color-ink-muted);\n}\n\n.btn-copy {\n  background: transparent;\n  border: 1px solid var(--color-card-border);\n  color: var(--color-ink-muted);\n  border-radius: 4px;\n  padding: 0.25rem 0.625rem;\n  font-size: 0.75rem;\n  font-weight: 600;\n  cursor: pointer;\n  min-height: 32px;\n}\n\n.btn-copy:hover {\n  background-color: var(--color-card-bg);\n  color: var(--color-ink);\n}\n\n.output-text-content {\n  font-size: 1.0625rem;\n  line-height: 1.65;\n  color: var(--color-ink);\n  white-space: pre-wrap;\n  word-break: break-word;\n  max-height: 240px;\n  overflow-y: auto;\n  padding-right: 0.25rem;\n}\n\n/* Audio Player Section */\n.audio-section {\n  display: flex;\n  flex-direction: column;\n  gap: 1rem;\n  padding-top: 0.5rem;\n}\n\n.audio-player-wrapper {\n  width: 100%;\n}\n\naudio {\n  width: 100%;\n  min-height: 48px;\n  border-radius: 8px;\n}\n\n/* Speed Controls */\n.playback-speed-group {\n  display: flex;\n  align-items: center;\n  gap: 0.75rem;\n  flex-wrap: wrap;\n}\n\n.speed-label {\n  font-size: 0.875rem;\n  font-weight: 600;\n  color: var(--color-ink-muted);\n}\n\n.speed-buttons {\n  display: flex;\n  gap: 0.375rem;\n}\n\n.speed-btn {\n  min-height: var(--min-touch-size);\n  min-width: var(--min-touch-size);\n  padding: 0.375rem 0.625rem;\n  font-family: var(--font-ui);\n  font-size: 0.875rem;\n  font-weight: 600;\n  color: var(--color-ink-muted);\n  background-color: var(--color-card-bg);\n  border: 1px solid var(--color-card-border);\n  border-radius: 6px;\n  cursor: pointer;\n  transition: all 0.15s ease;\n}\n\n.speed-btn:hover {\n  background-color: var(--color-forest-tint);\n  color: var(--color-forest);\n}\n\n.speed-btn.active,\n.speed-btn[aria-pressed=\"true\"] {\n  background-color: var(--color-forest);\n  color: var(--color-forest-contrast);\n  border-color: var(--color-forest);\n}\n\n/* Footer */\n.app-footer {\n  border-top: 1px solid var(--color-card-border);\n  background-color: var(--color-bg);\n  padding: 2.25rem 1.5rem;\n  margin-top: auto;\n}\n\n.footer-container {\n  max-width: 1120px;\n  margin: 0 auto;\n  display: flex;\n  flex-direction: column;\n  gap: 0.625rem;\n}\n\n.footer-tagline {\n  font-size: 0.9375rem;\n  font-weight: 700;\n  color: var(--color-forest);\n}\n\n.footer-disclaimer {\n  font-size: 0.875rem;\n  line-height: 1.5;\n  color: var(--color-ink-muted);\n  max-width: 720px;\n}\n\n/* Responsive Breakpoints */\n@media (max-width: 860px) {\n  .reader-grid {\n    grid-template-columns: 1fr;\n    gap: 1.5rem;\n  }\n\n  .languages-grid {\n    grid-template-columns: 1fr;\n  }\n\n  .card {\n    padding: 1.5rem;\n  }\n\n  .app-header {\n    padding: 1.25rem 1rem 1.75rem;\n  }\n\n  .app-main {\n    padding: 1.5rem 1rem 2.5rem;\n  }\n}\n","news.js":"(() => {\n  'use strict';\n  const reader = document.querySelector('.app-main');\n  const header = document.querySelector('.header-container');\n  if (!reader || !header) return;\n  const el = (tag, className, text) => {\n    const node = document.createElement(tag);\n    if (className) node.className = className;\n    if (text !== undefined) node.textContent = text;\n    return node;\n  };\n  const store = {get(k, fallback) {try {return localStorage.getItem(k) || fallback;} catch {return fallback;}}, set(k,v) {try {localStorage.setItem(k,v);} catch {}}};\n  const nav = el('nav', 'mode-switch'); nav.setAttribute('aria-label','Choose Suno mode');\n  const readerButton = el('button','mode-button','Text Reader'); readerButton.type='button';\n  const newsButton = el('button','mode-button','News Mirror'); newsButton.type='button';\n  const newBadge=el('span','new-mode-badge','NEW'); newsButton.append(newBadge);\n  nav.append(readerButton,newsButton); header.querySelector('.brand-bar').after(nav);\n  const section=el('main','news-mode'); section.id='news-mode'; section.hidden=true;\n  section.innerHTML=`<div class=\"news-shell\">\n    <div class=\"news-intro\"><div><p class=\"news-eyebrow\">YOUR WORLD. YOUR LANGUAGE. YOUR VOICE.</p><h2>Your personal listening edition.</h2><p>Choose what matters to you. Hear current headlines in your language, with an optional AI recreation of your own voice.</p></div><span class=\"news-edition-mark\" aria-hidden=\"true\">N / M</span></div>\n    <div class=\"news-controls\"><div><label for=\"news-topic\">Your interests</label><select id=\"news-topic\"><option value=\"india\">India headlines</option><option value=\"world\">World affairs</option><option value=\"technology\">Technology</option><option value=\"science\">Science & environment</option><option value=\"business\">Business</option></select></div><div><label for=\"news-language\">Your listening language</label><select id=\"news-language\"></select></div><button type=\"button\" id=\"news-refresh\" class=\"btn btn-secondary\">Refresh headlines</button></div>\n    <div class=\"news-feed-meta\"><span id=\"news-freshness\">Headlines update from the source.</span><span class=\"news-poll-note\">Checks every minute while this view is open</span></div>\n    <p id=\"news-status\" class=\"news-status\" role=\"status\" aria-live=\"polite\"></p>\n    <div class=\"news-layout\"><section class=\"news-feed\" aria-label=\"Current news headlines\"><div id=\"news-cards\" class=\"news-cards\"></div></section>\n    <aside class=\"news-listening card\" aria-labelledby=\"news-listening-title\"><p class=\"news-eyebrow\">THE LISTENING ROOM</p><h3 id=\"news-listening-title\">A familiar way to hear the world.</h3><p class=\"news-listen-hint\">Choose a headline to create a short spoken reading. Your first reading uses Sarvam's standard voice.</p>\n      <div id=\"news-output\" hidden><span id=\"news-audio-kind\" class=\"badge\">Standard voice</span><h4 id=\"news-output-title\"></h4><p id=\"news-output-text\" class=\"news-output-text\"></p><audio id=\"news-audio\" controls preload=\"metadata\"></audio></div>\n      <p id=\"news-audio-status\" class=\"news-status\" role=\"status\" aria-live=\"polite\"></p>\n      <div class=\"voice-mirror-box\"><span class=\"voice-beta\">OPTIONAL · BETA</span><h4>Make it sound more like you.</h4><p>Upload a clean, single-speaker WAV recording of yourself, ideally 10–15 seconds. Accent and expression matching can vary.</p><label for=\"news-voice-file\" class=\"voice-file-label\">Your voice sample (WAV, up to 10 MB)</label><input id=\"news-voice-file\" type=\"file\" accept=\".wav,audio/wav,audio/x-wav\"><label class=\"news-consent\"><input type=\"checkbox\" id=\"news-voice-consent\"><span>This is my voice, and I consent to sending this recording to Sarvam to generate an AI recreation for this reading.</span></label><button type=\"button\" id=\"news-clone\" class=\"btn btn-primary\" disabled>Read in my voice (beta)</button><p class=\"voice-private-note\">Used only when you press the button. No sample is uploaded just by selecting it.</p></div>\n    </aside></div>\n    <p class=\"news-transparency\">A listening aid, not a news publisher. Headlines and excerpts come from linked sources; publication times belong to the publisher. Translations and voices are AI-generated. New stories depend on source updates.</p>\n  </div>`;\n  reader.before(section);\n  const $=s=>section.querySelector(s);\n  const topic=$('#news-topic'),language=$('#news-language'),cards=$('#news-cards'),status=$('#news-status'),freshness=$('#news-freshness'),refresh=$('#news-refresh');\n  const audio=$('#news-audio'),audioStatus=$('#news-audio-status'),output=$('#news-output'),sample=$('#news-voice-file'),consent=$('#news-voice-consent'),clone=$('#news-clone');\n  const languageOptions=[['en-IN','English'],['hi-IN','हिन्दी · Hindi'],['bn-IN','বাংলা · Bengali'],['gu-IN','ગુજરાતી · Gujarati'],['kn-IN','ಕನ್ನಡ · Kannada'],['ml-IN','മലയാളം · Malayalam'],['mr-IN','मराठी · Marathi'],['or-IN','ଓଡ଼ିଆ · Odia'],['pa-IN','ਪੰਜਾਬੀ · Punjabi'],['ta-IN','தமிழ் · Tamil'],['te-IN','తెలుగు · Telugu']];\n  for(const [value,name] of languageOptions) {const o=el('option','',name);o.value=value;language.append(o);}\n  const savedTopic=store.get('suno_news_topic','india'); if([...topic.options].some(o=>o.value===savedTopic))topic.value=savedTopic;\n  const savedLanguage=store.get('suno_news_language','hi-IN'); if(languageOptions.some(o=>o[0]===savedLanguage))language.value=savedLanguage;\n  let active=false,fetching=false,busy=false,prepared=null,audioUrl=null,feedController=null,feedVersion=0;\n  const dateLabel=value=>{if(!value)return 'Publication time unavailable';const d=new Date(value);return Number.isNaN(d.getTime())?'Publication time unavailable':d.toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short'});};\n  function cloneState() {clone.disabled=busy||!prepared||!sample.files?.[0]||!consent.checked;}\n  function setBusy(value) {busy=value;language.disabled=value;sample.disabled=value;consent.disabled=value;for(const b of cards.querySelectorAll('button'))b.disabled=value;cloneState();}\n  function stopAudio() {audio.pause();audio.removeAttribute('src');audio.load();if(audioUrl)URL.revokeObjectURL(audioUrl);audioUrl=null;}\n  function setAudio(base64,mime) {\n    if(typeof base64!=='string'||!base64)throw Error('No audio was returned.');\n    const bytes=Uint8Array.from(atob(base64),c=>c.charCodeAt(0));\n    stopAudio();audioUrl=URL.createObjectURL(new Blob([bytes],{type:mime||'audio/wav'}));audio.src=audioUrl;\n  }\n  async function fetchNews() {\n    if(fetching||!active||document.hidden)return;\n    fetching=true;refresh.disabled=true;const version=++feedVersion;feedController=new AbortController();status.textContent='Checking the publisher for current headlines…';\n    try {\n      const r=await fetch('/api/news?topic='+encodeURIComponent(topic.value),{signal:feedController.signal});\n      const data=await r.json();if(!r.ok)throw Error(data.error||'Headlines are unavailable right now.');\n      if(version!==feedVersion)return;\n      cards.replaceChildren();\n      for(const item of (data.items||[]).slice(0,5)) {\n        let sourceUrl;try{sourceUrl=new URL(item.url);if(sourceUrl.protocol!=='https:')continue;}catch{continue;}\n        const card=el('article','news-story');\n        const meta=el('div','news-story-meta');meta.append(el('span','news-source',item.source||'News source'),el('time','',dateLabel(item.publishedAt)));\n        const title=el('h3','',String(item.title||''));const description=el('p','news-excerpt',String(item.description||''));\n        const actions=el('div','news-story-actions');const listen=el('button','btn btn-primary','Listen in my language');listen.type='button';listen.disabled=busy;listen.addEventListener('click',()=>listenStory(item));\n        const source=el('a','news-source-link','Read original ↗');source.href=sourceUrl.href;source.target='_blank';source.rel='noopener noreferrer';\n        actions.append(listen,source);card.append(meta,title,description,actions);cards.append(card);\n      }\n      freshness.textContent='Last checked '+dateLabel(data.fetchedAt||new Date().toISOString());\n      status.textContent=cards.children.length?'Choose a story to hear your edition.'+(data.unavailableSources?.length?' Some publishers are temporarily unavailable.':''):'No current headlines were returned. Try another topic.';\n    } catch(error) {if(version===feedVersion&&error.name!=='AbortError')status.textContent=error.message||'Cannot load headlines. Please try again.';}finally{if(version===feedVersion){fetching=false;refresh.disabled=false;}}\n  }\n  async function listenStory(item) {\n    if(busy)return;setBusy(true);prepared=null;stopAudio();output.hidden=true;audioStatus.textContent='Preparing this headline in your listening language…';\n    const target=language.value;\n    try {\n      const text=Array.from(String(item.title||'')+'. '+String(item.description||'')).slice(0,650).join('');\n      const r=await fetch('/api/read',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({text,sourceLanguage:'en-IN',targetLanguage:target})});\n      const data=await r.json();\n      if(typeof data.text==='string'&&data.text.trim()) {\n        prepared={text:data.text,languageCode:target,title:String(item.title||'')};\n        $('#news-output-title').textContent=prepared.title;$('#news-output-text').textContent=prepared.text;$('#news-output-text').lang=target;output.hidden=false;\n      }\n      if(!r.ok)throw Error(data.error||'This reading could not be created.');\n      setAudio(data.audioBase64,data.mimeType);$('#news-audio-kind').textContent='Standard voice · AI-generated';\n      audioStatus.textContent='Your reading is ready. Press play to listen.';\n    }catch(error){audioStatus.textContent=error.message||'Unable to create this reading.';}finally{setBusy(false);}\n  }\n  async function cloneReading() {\n    if(busy||!prepared||!consent.checked)return;\n    const file=sample.files?.[0];if(!file)return;\n    if(!/\\.wav$/i.test(file.name)||file.size>10*1024*1024||file.size<44){audioStatus.textContent='Choose a WAV recording no larger than 10 MB, with one speaker and at most 15 seconds.';return;}\n    setBusy(true);audioStatus.textContent='Creating an AI version of your voice. Your standard reading stays available while you wait…';\n    try {\n      const bytes=new Uint8Array(await file.arrayBuffer());let raw='';for(let i=0;i<bytes.length;i+=32768)raw+=String.fromCharCode(...bytes.subarray(i,i+32768));\n      if(!consent.checked||sample.files?.[0]!==file)throw Error('Voice permission changed. Please confirm your sample again.');\n      const r=await fetch('/api/news-voice',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({text:prepared.text,languageCode:prepared.languageCode,referenceAudio:btoa(raw),consent:true})});\n      const data=await r.json();if(!r.ok)throw Error(data.error||'Your voice reading could not be generated.');\n      setAudio(data.audioBase64,data.mimeType);$('#news-audio-kind').textContent='Your voice · AI recreation';audioStatus.textContent='Your AI voice reading is ready. Voice likeness and accent may vary.';\n    }catch(error){audioStatus.textContent=(error.message||'Voice generation failed.')+(audioUrl?' Your standard audio remains available.':' Your prepared text remains readable.');}finally{setBusy(false);}\n  }\n  function setMode(news) {\n    active=news;section.hidden=!news;reader.hidden=news;readerButton.setAttribute('aria-pressed',String(!news));newsButton.setAttribute('aria-pressed',String(news));\n    if(!news){audio.pause();feedVersion++;fetching=false;refresh.disabled=false;if(feedController)feedController.abort();}else fetchNews();\n  }\n  readerButton.addEventListener('click',()=>setMode(false));newsButton.addEventListener('click',()=>setMode(true));\n  refresh.addEventListener('click',fetchNews);\n  topic.addEventListener('change',()=>{store.set('suno_news_topic',topic.value);if(feedController)feedController.abort();fetching=false;fetchNews();});\n  language.addEventListener('change',()=>{store.set('suno_news_language',language.value);prepared=null;stopAudio();output.hidden=true;consent.checked=false;cloneState();audioStatus.textContent='Language changed. Choose a headline to create a new reading.';});\n  sample.addEventListener('change',()=>{consent.checked=false;cloneState();});consent.addEventListener('change',cloneState);clone.addEventListener('click',cloneReading);\n  setInterval(()=>{if(active&&!document.hidden)fetchNews();},60000);\n  document.addEventListener('visibilitychange',()=>{if(!document.hidden&&active)fetchNews();});\n  window.addEventListener('pagehide',()=>{if(audioUrl)URL.revokeObjectURL(audioUrl);if(feedController)feedController.abort();});\n  setMode(true);\n})();\n","news.css":".mode-switch{display:flex;gap:8px;margin:24px 0 0;align-items:center}.mode-button{min-height:44px;border:1px solid var(--color-card-border);border-radius:999px;background:var(--color-card-bg);color:var(--color-ink);padding:9px 20px;font:600 .9rem var(--font-ui);cursor:pointer}.mode-button[aria-pressed=\"true\"]{background:var(--color-forest);border-color:var(--color-forest);color:var(--color-forest-contrast)}.new-mode-badge{font-size:.62rem;letter-spacing:.08em;margin-left:8px;opacity:.8}.news-mode{color:var(--color-ink);background:var(--color-bg);border-top:1px solid var(--color-card-border)}.news-shell{max-width:1160px;margin:auto;padding:42px 24px 52px}.news-intro{display:flex;align-items:center;justify-content:space-between;gap:24px;margin-bottom:30px}.news-intro h2{font:700 clamp(1.8rem,4vw,2.8rem)/1.12 var(--font-editorial);margin:10px 0 14px;letter-spacing:-.035em}.news-intro p:not(.news-eyebrow){max-width:670px;color:var(--color-ink-muted);font-size:1.05rem;line-height:1.6}.news-eyebrow{font:700 .71rem var(--font-ui);letter-spacing:.13em;color:var(--color-forest);margin:0 0 12px}.news-edition-mark{font:italic 700 4.5rem var(--font-editorial);color:var(--color-forest);letter-spacing:-.06em;opacity:.25;white-space:nowrap}.news-controls{padding:20px 22px;background:var(--color-forest-tint);border:1px solid var(--color-forest-border);border-radius:14px;display:flex;align-items:flex-end;gap:18px}.news-controls>div{flex:1}.news-controls label,.voice-file-label{display:block;font-weight:650;font-size:.86rem;margin-bottom:8px}.news-controls select{width:100%;min-height:46px;border:1px solid var(--color-card-border);border-radius:8px;padding:10px 12px;color:var(--color-ink);background:var(--color-card-bg);font:inherit}.news-controls button{white-space:nowrap}.news-feed-meta{display:flex;justify-content:space-between;gap:15px;font-size:.75rem;color:var(--color-ink-muted);margin:14px 2px}.news-poll-note{color:var(--color-ink-muted)}.news-status{font-size:.87rem;line-height:1.6;color:var(--color-ink-muted);min-height:1.5em;margin:12px 0 20px}.news-layout{display:grid;grid-template-columns:minmax(0,1.15fr) minmax(0,.85fr);gap:26px;align-items:start}.news-cards{display:grid;gap:16px}.news-story{padding:25px;background:var(--color-card-bg);border:1px solid var(--color-card-border);border-radius:13px;box-shadow:var(--shadow-card)}.news-story-meta{display:flex;justify-content:space-between;gap:12px;font-size:.68rem;line-height:1.6;color:var(--color-ink-muted);margin-bottom:13px}.news-source{color:var(--color-forest);font-weight:750;text-transform:uppercase;letter-spacing:.08em}.news-story h3{font:700 1.45rem/1.25 var(--font-editorial);letter-spacing:-.015em;margin:0 0 12px}.news-excerpt{font-size:.91rem;line-height:1.65;color:var(--color-ink-muted);margin:0 0 20px}.news-story-actions{display:flex;align-items:center;justify-content:space-between;gap:14px;flex-wrap:wrap}.news-story-actions .btn{font-size:.8rem;padding:10px 15px}.news-source-link{display:inline-flex;align-items:center;min-height:44px;color:var(--color-forest);font-size:.8rem;font-weight:650;text-underline-offset:3px}.news-listening{padding:26px;position:sticky;top:18px}.news-listening h3{font:700 1.7rem/1.2 var(--font-editorial);margin:8px 0 15px}.news-listen-hint{font-size:.89rem;color:var(--color-ink-muted);line-height:1.65}.news-listening h4{font:700 1.15rem/1.35 var(--font-editorial);margin:16px 0 12px}.news-output-text{line-height:1.85;font-size:1.05rem;padding:16px;border-radius:10px;background:var(--color-bg-subtle);white-space:pre-wrap;overflow-wrap:anywhere}.news-listening audio{width:100%;margin:12px 0}.voice-mirror-box{border-top:1px solid var(--color-card-border);margin-top:24px;padding-top:24px}.voice-beta{font-size:.65rem;letter-spacing:.12em;font-weight:750;color:var(--color-forest)}.voice-mirror-box>p{font-size:.82rem;line-height:1.65;color:var(--color-ink-muted)}.voice-mirror-box input[type=file]{width:100%;font:inherit;font-size:.76rem;color:var(--color-ink);padding:11px 0;min-height:44px}.voice-mirror-box input[type=file]::file-selector-button{padding:10px 12px;margin-right:8px;border:1px solid var(--color-card-border);border-radius:6px;background:var(--color-bg-subtle);color:var(--color-ink);cursor:pointer}.news-consent{display:flex;gap:10px;align-items:flex-start;font-size:.75rem;line-height:1.6;margin:14px 0 18px;cursor:pointer}.news-consent input{flex-shrink:0;width:19px;height:19px;margin-top:2px;accent-color:var(--color-forest)}.voice-mirror-box .btn{width:100%;font-size:.85rem}.voice-private-note{font-size:.7rem!important}.news-transparency{font-size:.74rem;line-height:1.7;color:var(--color-ink-muted);border-top:1px solid var(--color-card-border);margin:30px 0 0;padding-top:22px}.news-mode button:disabled{opacity:.5;cursor:not-allowed}.news-mode [hidden]{display:none!important}@media(max-width:760px){.news-layout{grid-template-columns:1fr}.news-listening{position:static}.news-controls{flex-wrap:wrap}.news-controls>div{min-width:calc(50% - 18px)}.news-controls button{width:100%}.news-edition-mark{display:none}.news-feed-meta{display:block}.news-poll-note{display:block;margin-top:4px}.news-shell{padding:28px 16px 36px}.news-intro{margin-bottom:22px}.news-story{padding:21px}.news-story-meta{flex-wrap:wrap}.mode-switch{margin-top:20px}.mode-button{padding:9px 15px}}@media(max-width:420px){.news-controls>div{min-width:100%}.news-controls{padding:18px}.news-listening{padding:22px}.news-story-actions{align-items:stretch}.news-story-actions .btn{width:100%}}\n","voice-recorder.js":"(() => {\n  'use strict';\n  function init() {\n    const input = document.querySelector('#news-voice-file');\n    if (!input || document.querySelector('#news-record-voice')) return;\n    const box = document.createElement('div');\n    box.className = 'voice-recorder';\n    const record = document.createElement('button');\n    record.id = 'news-record-voice'; record.type = 'button'; record.className = 'btn btn-secondary';\n    record.textContent = 'Record my voice (12 seconds)';\n    const stop = document.createElement('button');\n    stop.type = 'button'; stop.className = 'btn btn-secondary'; stop.textContent = 'Stop recording'; stop.hidden = true;\n    const status = document.createElement('p'); status.className = 'news-status'; status.setAttribute('role', 'status'); status.setAttribute('aria-live', 'polite');\n    box.append(record, stop, status); input.after(box);\n    let stream, context, source, processor, silent, timer, recording = false, pending = false, frames = [], samples = 0, started = 0, generation = 0;\n    const sync = () => { record.disabled = input.disabled || recording || pending; };\n    new MutationObserver(sync).observe(input, {attributes:true, attributeFilter:['disabled']});\n    function cleanup() {\n      clearInterval(timer); timer = undefined;\n      if (processor) { processor.onaudioprocess = null; processor.disconnect(); }\n      if (source) source.disconnect();\n      if (silent) silent.disconnect();\n      if (stream) stream.getTracks().forEach(t => t.stop());\n      if (context) context.close().catch(() => {});\n      stream = context = source = processor = silent = undefined;\n      recording = pending = false; stop.hidden = true; sync();\n    }\n    function wav(rate) {\n      const buffer = new ArrayBuffer(44 + samples * 2), view = new DataView(buffer);\n      const text = (offset, value) => { for (let i=0;i<value.length;i++) view.setUint8(offset+i,value.charCodeAt(i)); };\n      text(0,'RIFF'); view.setUint32(4,36+samples*2,true); text(8,'WAVE'); text(12,'fmt '); view.setUint32(16,16,true);\n      view.setUint16(20,1,true); view.setUint16(22,1,true); view.setUint32(24,rate,true); view.setUint32(28,rate*2,true);\n      view.setUint16(32,2,true); view.setUint16(34,16,true); text(36,'data'); view.setUint32(40,samples*2,true);\n      let offset = 44;\n      for (const frame of frames) for (const value of frame) { const n=Math.max(-1,Math.min(1,value));view.setInt16(offset,n<0?n*32768:n*32767,true);offset+=2; }\n      return new File([buffer], 'my-voice-sample.wav', {type:'audio/wav'});\n    }\n    function finish(save=true) {\n      generation++;\n      if (!recording) { cleanup(); return; }\n      const rate = context.sampleRate;\n      let file;\n      if (save && samples >= rate) file = wav(rate);\n      cleanup(); frames=[]; samples=0;\n      if (!save) return;\n      if (!file) { status.textContent='Recording was too short. Please record at least one second.'; return; }\n      try {\n        const transfer = new DataTransfer(); transfer.items.add(file); input.files = transfer.files; input.dispatchEvent(new Event('change', {bubbles:true}));\n        status.textContent='Voice sample ready. Nothing has been uploaded. Confirm consent before creating your reading.';\n      } catch { status.textContent='Unable to attach this recording. Please choose a WAV file instead.'; }\n    }\n    record.addEventListener('click', async () => {\n      if (input.disabled || recording || pending) return;\n      if (!navigator.mediaDevices?.getUserMedia || !(window.AudioContext || window.webkitAudioContext)) { status.textContent='Microphone recording is unavailable in this browser. Choose a WAV file instead.'; return; }\n      pending=true; sync(); const token=++generation;\n      status.textContent='Allow microphone access, then speak clearly in your natural voice. Only you should speak.';\n      try {\n        const granted = await navigator.mediaDevices.getUserMedia({audio:{channelCount:1,echoCancellation:true,noiseSuppression:true}});\n        if (token!==generation || input.disabled) { granted.getTracks().forEach(t=>t.stop()); cleanup(); return; }\n        stream=granted; context=new (window.AudioContext || window.webkitAudioContext)(); await context.resume();\n        if (token!==generation) { cleanup(); return; }\n        source=context.createMediaStreamSource(stream); processor=context.createScriptProcessor(4096,1,1); silent=context.createGain(); silent.gain.value=0;\n        frames=[]; samples=0; const limit=Math.floor(context.sampleRate*12);\n        processor.onaudioprocess = event => {\n          if (!recording) return;\n          const data=event.inputBuffer.getChannelData(0); const chunk=data.slice(0,Math.max(0,limit-samples)); frames.push(chunk); samples+=chunk.length;\n          if (samples>=limit) finish();\n        };\n        source.connect(processor); processor.connect(silent); silent.connect(context.destination);\n        pending=false; recording=true; started=Date.now(); stop.hidden=false; sync();\n        const tick=()=>{const elapsed=Math.min(12,Math.floor((Date.now()-started)/1000));status.textContent=`Recording: ${elapsed} / 12 seconds. Speak clearly; one speaker only.`;if(elapsed>=12)finish();};\n        tick(); timer=setInterval(tick,250);\n      } catch { cleanup(); status.textContent='Microphone access was denied or unavailable. Allow microphone access and try again, or choose a WAV file.'; }\n    });\n    stop.addEventListener('click',()=>finish());\n    window.addEventListener('pagehide',()=>finish(false));\n    window.addEventListener('beforeunload',()=>finish(false));\n    sync();\n  }\n  if (document.readyState==='loading') document.addEventListener('DOMContentLoaded',init,{once:true}); else init();\n})();\r\n"};
